import axios from "axios";
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../Redux/Slice";

export default function Products() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  const dispatch = useDispatch();
  const navigate = useNavigate();

  // Redux Cart Items
  const cartItems = useSelector(
    (state) => state.cart.items
  );

  // =========================
  // GET PRODUCTS
  // =========================

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      const response = await axios.get(
        "http://localhost:5000/api/v1/products",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      console.log("Products:", response.data);

      setProducts(response.data.data || []);
    } catch (error) {
      console.error(
        error.response?.data || error.message
      );

      setError(
        error.response?.data?.message ||
          "Unable to load products."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // =========================
  // SEARCH PRODUCTS
  // =========================

  const filteredProducts = useMemo(() => {
    return products.filter((item) =>
      item.name
        ?.toLowerCase()
        .includes(search.toLowerCase())
    );
  }, [products, search]);

  // =========================
  // STOCK DATA
  // =========================

  const inStock = products.filter(
    (item) => Number(item.quantity ?? item.stock ?? 0) > 0
  ).length;

  const lowStock = products.filter((item) => {
    const stock = Number(
      item.quantity ?? item.stock ?? 0
    );

    return stock > 0 && stock <= 10;
  }).length;

  // =========================
  // PRODUCT CARD
  // =========================

  const renderProductCard = (item) => {
    const isInCart = cartItems.some(
      (cartItem) => cartItem.id === item.id
    );

    const stock = Number(
      item.quantity ?? item.stock ?? 0
    );

    return (
      <div
        className="product-column"
        key={item.id}
      >
        <div className="product-item-card">

          {/* IMAGE */}

          <div className="product-image-wrapper">

            <img
              src={
                item.image ||
                "https://via.placeholder.com/500x400?text=No+Image"
              }
              alt={item.name}
              className="product-image"
            />

            <span className="product-id">
              #{item.id}
            </span>

            {stock > 0 && stock <= 10 && (
              <span className="low-stock-badge">
                Low Stock
              </span>
            )}

            {stock > 10 && (
              <span className="stock-badge">
                In Stock
              </span>
            )}

          </div>

          {/* DETAILS */}

          <div className="product-details">

            <div className="product-category">
              PRODUCT
            </div>

            <h3 className="product-title">
              {item.name}
            </h3>

            <p className="product-description">
              {item.description ||
                "No description available for this product."}
            </p>

            {/* PRICE + STOCK */}

            <div className="product-meta">

              <div>
                <span className="price-label">
                  Price
                </span>

                <div className="product-price">
                  ₹
                  {Number(
                    item.price || 0
                  ).toLocaleString("en-IN")}
                </div>
              </div>

              <div className="stock-info">
                <span className="price-label">
                  Stock
                </span>

                <strong>
                  {stock > 0
                    ? `${stock} units`
                    : "Unavailable"}
                </strong>
              </div>

            </div>

            {/* ADD CART */}

            <button
              className={`add-cart-btn ${
                isInCart ? "added" : ""
              }`}
              disabled={isInCart}
              onClick={() =>
                dispatch(addToCart(item))
              }
            >
              <span className="cart-icon">
                {isInCart ? "✓" : "🛒"}
              </span>

              <span>
                {isInCart
                  ? "Added to Cart"
                  : "Add to Cart"}
              </span>
            </button>

          </div>
        </div>
      </div>
    );
  };

  return (
    <>
      <style>{`

        /* =========================
           PRODUCTS PAGE
        ========================= */

        .products-page {
          min-height: 100vh;
          padding: 30px;
          background: #f8fafc;
          color: #0f172a;
          box-sizing: border-box;
        }

        /* =========================
           HEADER
        ========================= */

        .products-header {
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
          gap: 20px;
          margin-bottom: 28px;
        }

        .products-label {
          color: #2563eb;
          font-size: 11px;
          font-weight: 800;
          letter-spacing: 1.5px;
          margin-bottom: 7px;
        }

        .products-header h1 {
          margin: 0;
          font-size: 30px;
          font-weight: 800;
          color: #0f172a;
        }

        .products-header p {
          margin: 8px 0 0;
          color: #64748b;
          font-size: 14px;
        }

        .add-product-btn {
          border: none;
          background: linear-gradient(
            135deg,
            #2563eb,
            #1d4ed8
          );
          color: white;
          padding: 12px 18px;
          border-radius: 10px;
          font-size: 13px;
          font-weight: 700;
          cursor: pointer;
          box-shadow:
            0 6px 15px rgba(37, 99, 235, 0.2);
          transition: 0.25s ease;
          white-space: nowrap;
        }

        .add-product-btn:hover {
          transform: translateY(-2px);
          box-shadow:
            0 10px 20px rgba(37, 99, 235, 0.28);
        }

        /* =========================
           STATS
        ========================= */

        .product-stats {
          display: grid;
          grid-template-columns:
            repeat(4, 1fr);
          gap: 18px;
          margin-bottom: 25px;
        }

        .product-stat-card {
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 14px;
          padding: 18px;
          display: flex;
          align-items: center;
          gap: 14px;
          box-shadow:
            0 4px 15px rgba(15, 23, 42, 0.04);
          transition: 0.25s ease;
        }

        .product-stat-card:hover {
          transform: translateY(-3px);
          box-shadow:
            0 8px 20px rgba(15, 23, 42, 0.08);
        }

        .stat-icon {
          width: 45px;
          height: 45px;
          border-radius: 11px;
          display: flex;
          align-items: center;
          justify-content: center;
          background: #eff6ff;
          font-size: 20px;
          flex-shrink: 0;
        }

        .stat-info span {
          display: block;
          color: #64748b;
          font-size: 11px;
          font-weight: 600;
          margin-bottom: 4px;
        }

        .stat-info strong {
          color: #0f172a;
          font-size: 20px;
          font-weight: 800;
        }

        /* =========================
           SEARCH BAR
        ========================= */

        .products-toolbar {
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 14px;
          padding: 16px;
          margin-bottom: 25px;
          display: flex;
          justify-content: space-between;
          align-items: center;
          gap: 15px;
        }

        .search-wrapper {
          position: relative;
          flex: 1;
          max-width: 500px;
        }

        .search-icon {
          position: absolute;
          left: 15px;
          top: 50%;
          transform: translateY(-50%);
          color: #94a3b8;
          font-size: 16px;
        }

        .product-search {
          width: 100%;
          height: 44px;
          padding: 0 15px 0 42px;
          border: 1px solid #e2e8f0;
          border-radius: 9px;
          outline: none;
          font-size: 13px;
          color: #334155;
          box-sizing: border-box;
          transition: 0.2s ease;
        }

        .product-search:focus {
          border-color: #2563eb;
          box-shadow:
            0 0 0 3px
            rgba(37, 99, 235, 0.08);
        }

        .product-count {
          color: #64748b;
          font-size: 12px;
          font-weight: 600;
          white-space: nowrap;
        }

        .product-count strong {
          color: #2563eb;
        }

        /* =========================
           PRODUCT GRID
        ========================= */

        .products-grid {
          display: grid;
          grid-template-columns:
            repeat(4, minmax(0, 1fr));
          gap: 20px;
        }

        .product-column {
          min-width: 0;
        }

        /* =========================
           PRODUCT CARD
        ========================= */

        .product-item-card {
          height: 100%;
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 16px;
          overflow: hidden;
          box-shadow:
            0 5px 18px
            rgba(15, 23, 42, 0.05);
          transition:
            transform 0.3s ease,
            box-shadow 0.3s ease;
        }

        .product-item-card:hover {
          transform: translateY(-7px);
          box-shadow:
            0 15px 35px
            rgba(15, 23, 42, 0.11);
        }

        /* =========================
           IMAGE
        ========================= */

        .product-image-wrapper {
          position: relative;
          height: 220px;
          background: #f1f5f9;
          overflow: hidden;
        }

        .product-image {
          width: 100%;
          height: 100%;
          object-fit: cover;
          display: block;
          transition:
            transform 0.5s ease,
            filter 0.5s ease;
        }

        .product-item-card:hover
        .product-image {
          transform: scale(1.07);
          filter: brightness(1.04);
        }

        .product-id {
          position: absolute;
          top: 12px;
          left: 12px;
          padding: 5px 9px;
          background:
            rgba(15, 23, 42, 0.82);
          color: white;
          border-radius: 20px;
          font-size: 10px;
          font-weight: 700;
          backdrop-filter: blur(5px);
        }

        .stock-badge,
        .low-stock-badge {
          position: absolute;
          top: 12px;
          right: 12px;
          padding: 5px 9px;
          border-radius: 20px;
          font-size: 10px;
          font-weight: 700;
        }

        .stock-badge {
          background: #dcfce7;
          color: #15803d;
        }

        .low-stock-badge {
          background: #fef3c7;
          color: #b45309;
        }

        /* =========================
           DETAILS
        ========================= */

        .product-details {
          padding: 18px;
          display: flex;
          flex-direction: column;
          height: calc(100% - 220px);
          box-sizing: border-box;
        }

        .product-category {
          color: #2563eb;
          font-size: 9px;
          font-weight: 800;
          letter-spacing: 1.2px;
          margin-bottom: 6px;
        }

        .product-title {
          margin: 0;
          color: #1e293b;
          font-size: 17px;
          font-weight: 750;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .product-description {
          color: #64748b;
          font-size: 12px;
          line-height: 1.6;
          margin: 8px 0 15px;

          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;

          min-height: 38px;
        }

        /* =========================
           META
        ========================= */

        .product-meta {
          display: flex;
          justify-content: space-between;
          align-items: flex-end;
          padding: 12px 0;
          border-top: 1px solid #f1f5f9;
          border-bottom: 1px solid #f1f5f9;
          margin-bottom: 15px;
        }

        .price-label {
          display: block;
          color: #94a3b8;
          font-size: 10px;
          font-weight: 600;
          margin-bottom: 3px;
        }

        .product-price {
          color: #15803d;
          font-size: 19px;
          font-weight: 800;
        }

        .stock-info {
          text-align: right;
        }

        .stock-info strong {
          color: #334155;
          font-size: 11px;
        }

        /* =========================
           CART BUTTON
        ========================= */

        .add-cart-btn {
          width: 100%;
          border: none;
          border-radius: 9px;
          padding: 11px 14px;
          background: #2563eb;
          color: white;
          font-size: 12px;
          font-weight: 700;
          cursor: pointer;

          display: flex;
          justify-content: center;
          align-items: center;
          gap: 8px;

          transition: 0.25s ease;
          margin-top: auto;
        }

        .add-cart-btn:hover:not(:disabled) {
          background: #1d4ed8;
          transform: translateY(-2px);
          box-shadow:
            0 6px 15px
            rgba(37, 99, 235, 0.22);
        }

        .add-cart-btn.added,
        .add-cart-btn:disabled {
          background: #16a34a;
          color: white;
          cursor: not-allowed;
        }

        .cart-icon {
          font-size: 15px;
        }

        /* =========================
           LOADING
        ========================= */

        .products-loading {
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 16px;
          padding: 70px 20px;
          text-align: center;
        }

        .loading-spinner {
          width: 38px;
          height: 38px;
          border: 4px solid #dbeafe;
          border-top-color: #2563eb;
          border-radius: 50%;
          animation: productSpin 0.8s linear infinite;
          margin: 0 auto 15px;
        }

        @keyframes productSpin {
          to {
            transform: rotate(360deg);
          }
        }

        .products-loading p {
          margin: 0;
          color: #64748b;
          font-size: 13px;
        }

        /* =========================
           ERROR
        ========================= */

        .products-error {
          background: #fff7ed;
          border: 1px solid #fed7aa;
          border-radius: 14px;
          padding: 25px;
          text-align: center;
          color: #c2410c;
        }

        .products-error button {
          margin-top: 12px;
          border: none;
          border-radius: 8px;
          padding: 9px 15px;
          background: #ea580c;
          color: white;
          font-size: 12px;
          font-weight: 700;
          cursor: pointer;
        }

        /* =========================
           EMPTY STATE
        ========================= */

        .products-empty {
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 16px;
          text-align: center;
          padding: 70px 20px;
        }

        .empty-icon {
          width: 65px;
          height: 65px;
          margin: 0 auto 15px;
          border-radius: 18px;
          background: #eff6ff;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 28px;
        }

        .products-empty h3 {
          margin: 0 0 7px;
          color: #1e293b;
          font-size: 18px;
        }

        .products-empty p {
          margin: 0 0 18px;
          color: #64748b;
          font-size: 13px;
        }

        /* =========================
           NO SEARCH RESULT
        ========================= */

        .no-search-result {
          grid-column: 1 / -1;
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 15px;
          text-align: center;
          padding: 50px 20px;
        }

        .no-search-result div {
          font-size: 35px;
          margin-bottom: 10px;
        }

        .no-search-result h3 {
          margin: 0 0 5px;
          font-size: 17px;
        }

        .no-search-result p {
          margin: 0;
          color: #64748b;
          font-size: 12px;
        }

        /* =========================
           TABLET
        ========================= */

        @media (max-width: 1200px) {
          .products-grid {
            grid-template-columns:
              repeat(3, minmax(0, 1fr));
          }

          .product-stats {
            grid-template-columns:
              repeat(2, 1fr);
          }
        }

        /* =========================
           MOBILE
        ========================= */

        @media (max-width: 768px) {

          .products-page {
            padding: 20px 15px;
          }

          .products-header {
            flex-direction: column;
            margin-bottom: 22px;
          }

          .products-header h1 {
            font-size: 25px;
          }

          .add-product-btn {
            width: 100%;
          }

          .product-stats {
            grid-template-columns: 1fr 1fr;
            gap: 12px;
          }

          .product-stat-card {
            padding: 14px;
          }

          .stat-icon {
            width: 38px;
            height: 38px;
            font-size: 17px;
          }

          .stat-info strong {
            font-size: 17px;
          }

          .products-toolbar {
            align-items: stretch;
            flex-direction: column;
          }

          .search-wrapper {
            max-width: none;
          }

          .product-count {
            text-align: right;
          }

          .products-grid {
            grid-template-columns:
              repeat(2, minmax(0, 1fr));
            gap: 15px;
          }

          .product-image-wrapper {
            height: 190px;
          }

          .product-details {
            height: calc(100% - 190px);
            padding: 15px;
          }

          .product-title {
            font-size: 15px;
          }

          .product-price {
            font-size: 17px;
          }
        }

        /* =========================
           SMALL MOBILE
        ========================= */

        @media (max-width: 500px) {

          .products-page {
            padding: 15px 10px;
          }

          .products-header h1 {
            font-size: 22px;
          }

          .products-header p {
            font-size: 12px;
          }

          .product-stats {
            grid-template-columns: 1fr 1fr;
          }

          .product-stat-card {
            gap: 9px;
            padding: 12px;
          }

          .stat-icon {
            width: 34px;
            height: 34px;
            font-size: 15px;
          }

          .stat-info span {
            font-size: 9px;
          }

          .stat-info strong {
            font-size: 15px;
          }

          .products-grid {
            grid-template-columns: 1fr;
          }

          .product-image-wrapper {
            height: 230px;
          }

          .product-details {
            height: calc(100% - 230px);
          }

          .product-title {
            font-size: 17px;
          }

          .product-price {
            font-size: 19px;
          }
        }

      `}</style>

      <div className="products-page">

        {/* =========================
            HEADER
        ========================= */}

        <div className="products-header">

          <div>
            <div className="products-label">
              🛍️ STORE CATALOG
            </div>

            <h1>Products</h1>

            <p>
              Manage your products and keep
              your store inventory organized.
            </p>
          </div>

          <button
            className="add-product-btn"
            onClick={() =>
              navigate("/add-product")
            }
          >
            + Add Product
          </button>

        </div>

        {/* =========================
            STATS
        ========================= */}

        <div className="product-stats">

          <div className="product-stat-card">

            <div className="stat-icon">
              📦
            </div>

            <div className="stat-info">
              <span>Total Products</span>
              <strong>
                {products.length}
              </strong>
            </div>

          </div>

          <div className="product-stat-card">

            <div className="stat-icon">
              ✓
            </div>

            <div className="stat-info">
              <span>In Stock</span>
              <strong>
                {inStock}
              </strong>
            </div>

          </div>

          <div className="product-stat-card">

            <div className="stat-icon">
              ⚠️
            </div>

            <div className="stat-info">
              <span>Low Stock</span>
              <strong>
                {lowStock}
              </strong>
            </div>

          </div>

          <div className="product-stat-card">

            <div className="stat-icon">
              🛒
            </div>

            <div className="stat-info">
              <span>Cart Items</span>
              <strong>
                {cartItems.length}
              </strong>
            </div>

          </div>

        </div>

        {/* =========================
            SEARCH
        ========================= */}

        {!loading && !error && (
          <div className="products-toolbar">

            <div className="search-wrapper">

              <span className="search-icon">
                🔍
              </span>

              <input
                type="text"
                className="product-search"
                placeholder="Search products by name..."
                value={search}
                onChange={(e) =>
                  setSearch(e.target.value)
                }
              />

            </div>

            <div className="product-count">
              Showing{" "}
              <strong>
                {filteredProducts.length}
              </strong>{" "}
              of{" "}
              <strong>
                {products.length}
              </strong>{" "}
              products
            </div>

          </div>
        )}

        {/* =========================
            LOADING
        ========================= */}

        {loading && (
          <div className="products-loading">

            <div className="loading-spinner"></div>

            <p>
              Loading products...
            </p>

          </div>
        )}

        {/* =========================
            ERROR
        ========================= */}

        {!loading && error && (
          <div className="products-error">

            <div>
              ⚠️
            </div>

            <strong>
              Unable to load products
            </strong>

            <p>
              {error}
            </p>

            <button
              onClick={fetchProducts}
            >
              Try Again
            </button>

          </div>
        )}

        {/* =========================
            EMPTY
        ========================= */}

        {!loading &&
          !error &&
          products.length === 0 && (
            <div className="products-empty">

              <div className="empty-icon">
                📦
              </div>

              <h3>
                No Products Found
              </h3>

              <p>
                Add your first product to
                start building your catalog.
              </p>

              <button
                className="add-product-btn"
                onClick={() =>
                  navigate("/add-product")
                }
              >
                + Add Product
              </button>

            </div>
          )}

        {/* =========================
            PRODUCT GRID
        ========================= */}

        {!loading &&
          !error &&
          products.length > 0 && (

            <div className="products-grid">

              {filteredProducts.length > 0 ? (
                filteredProducts.map(
                  renderProductCard
                )
              ) : (
                <div className="no-search-result">

                  <div>
                    🔍
                  </div>

                  <h3>
                    No matching products
                  </h3>

                  <p>
                    Try searching with a
                    different product name.
                  </p>

                </div>
              )}

            </div>
          )}

      </div>
    </>
  );
}
